package com.bank.core;

import java.util.logging.*;

public class CacheEqualityDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Small branch codes INSIDE the cache (-128..127)
        Integer smallA = 100; // Integer.valueOf(100) → cached object
        Integer smallB = 100; // same cached object
        log.info(() -> "smallA == smallB (value 100): " + (smallA == smallB)
                        + "  (cached → same reference)");
        log.info(() -> "smallA.equals(smallB)       : " + smallA.equals(smallB)
                        + "  (value compare)");

        // Larger branch codes OUTSIDE the cache
        Integer bigA = 1000; // Integer.valueOf(1000) → NEW object
        Integer bigB = 1000; // another NEW object
        log.warning(() -> "bigA == bigB (value 1000)   : " + (bigA == bigB)
                           + "  (NOT cached → different references)");
        log.info(() -> "bigA.equals(bigB)           : " + bigA.equals(bigB)
                        + "  (value compare — CORRECT)");

        // Unboxing to primitives always compares by value
        int p1 = bigA, p2 = bigB;
        log.info(() -> "unboxed p1 == p2            : " + (p1 == p2)
                        + "  (primitive value compare)");

        // Show the cache boundary explicitly
        Integer edgeIn  = 127;  Integer edgeIn2  = 127;  // cached
        Integer edgeOut = 128;  Integer edgeOut2 = 128;  // just outside
        log.info(() -> "127 == 127 : " + (edgeIn == edgeIn2)   + "  (last cached value)");
        log.warning(() -> "128 == 128 : " + (edgeOut == edgeOut2)
                           + "  (first UNcached value)");

        // Reading the current (possibly tuned) high bound reflectively-safe way:
        String high = System.getProperty("java.lang.Integer.IntegerCache.high", "127 (default)");
        log.info(() -> "IntegerCache.high = " + high
                        + "  (raise with -Djava.lang.Integer.IntegerCache.high=N)");

        log.info("RULE: always compare Integer with .equals() or unbox to primitives; never ==");
    }
}
